UPDATE companies SET description='Plantible Foods operates from Eldorado, Texas, where it produces Rubi Protein™, a proprietary ingredient derived from the aquatic plant Lemna.

The company grows Lemna on aqua farms that require no arable land and use a fraction of the water needed for conventional protein crops. The harvested biomass is processed to extract RuBisCO, marketed as Rubi Protein™, a complete protein containing all nine essential amino acids plus vitamin B12. The ingredient is neutral in flavor and free of major allergens.

Plantible sells its protein to food manufacturers formulating baked goods, plant-based meats, dairy alternatives, and sports nutrition products. In baked goods, the protein replicates the mouthfeel of butter and eggs or the elasticity of gluten; in plant-based meats it can replace methylcellulose binders while improving juiciness; in dairy alternatives it enhances texture and nutrition.

The founders frame the business as a response to a broken food system, aiming to deliver sustainable nutrition at scale. They cite the crop’s efficiency — ten times more protein per acre than soy with ten times less water — and its carbon capture as core advantages that differentiate the ingredient from other plant proteins.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Aqua farming of Lemna (duckweed)", "RuBisCO (Rubi Protein\u2122) extraction and purification", "Food-grade protein ingredient manufacturing", "Ingredient functionality testing for baked goods, meat and dairy alternatives"], "industries": ["Food and beverage", "Baked goods", "Plant-based meat", "Dairy alternatives", "Sports nutrition", "Alternative protein ingredients"], "materials": ["Lemna (duckweed)", "RuBisCO (Rubi Protein\u2122)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Rubi Protein\u2122 provides all nine essential amino acids and vitamin B12", "Allergen-free, neutral-tasting protein ingredient", "Aqua farming uses 10x less water than soy and zero arable land", "Lemna captures 10x more CO2 than a healthy forest", "Replaces chemical binders like methylcellulose in plant-based meat"], "facts_used": ["Headquarters in Eldorado, Texas -> db", "Co-founders Tony Martens and Maurits van de Ven -> page /", "Produce Rubi Protein\u2122 from Lemna -> page /", "Aqua farm method, 10x less water than soybeans -> page /", "Applications in baked goods, plant-based meat, dairy, sports nutrition -> page /", "Company described as biology company unlocking power of plants -> page /", "Rubi Protein\u2122 contains all nine essential amino acids and vitamin B12 -> page /", "Allergen-free, neutral taste -> page /", "Lemna captures 10x more CO2 than forest -> page /", "Replaces methylcellulose in plant-based meat -> page /", "Mimics eggs, butter, gluten functionality -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We grow Lemna and extract Rubi Protein\u2122 in a sustainable and efficient way.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='plantible-foods-eldorado' AND approved AND profile IS NULL;
UPDATE companies SET description='Plasman operates a manufacturing facility in Lawrenceburg, Tennessee, as part of a global automotive components company headquartered in Windsor, Canada, with a European headquarters in Gothenburg, Sweden. The Lawrenceburg site contributes to the company''s network of manufacturing, engineering, and sales locations serving automotive OEMs worldwide.

The company produces a range of automotive exterior and structural components, including window assemblies and regulators, rack lifts, door frames, roof rail systems, bumpers and fascias, grilles, and subsystem modules. Its production capabilities span injection molding, chroming, paint application, and fully automated robotic assembly, supported by more than 200 engineers and technicians dedicated to molding and over 290,000 square feet of tooling capacity. Surface finishing technologies include Omniluxe®, a physical vapor deposition process positioned as an environmentally friendly alternative to traditional chrome plating, and Brilliance, a paint-over-chrome finish.

Plasman serves automotive original equipment manufacturers globally, delivering single-source solutions from concept through completion. Its customer base extends across North America, Europe, and Asia, with the company emphasizing collaborative partnerships and the ability to manage complex, high-volume programs for major vehicle platforms.

The organization highlights its collaborative mindset and single-source model as key differentiators, aiming to provide design, tooling, molding, finishing, and assembly under one roof. The development of proprietary finishes such as Omniluxe® reflects a stated focus on meeting evolving environmental regulations and OEM demands for sustainable surface solutions.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Injection molding", "Chrome plating", "Paint application", "Robotic assembly", "Tooling design and build", "Surface finishing (PVD, paint-over-chrome)", "Design and engineering", "Exterior trim manufacturing", "Bumper/fascia production", "Grille manufacturing", "Subsystem assembly"], "industries": ["Automotive OEM", "Automotive"], "materials": [], "equipment": ["Fully automated, complex robotic assembly systems"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Lawrenceburg, Tennessee location -> db", "Global HQ Windsor, Canada; European HQ Gothenburg, Sweden -> /about-us", "Operates in 9 countries -> /about-us", "Over 45 years history, started as two-person tool shop -> /about-us", "Thousands of employees worldwide -> /about-us", "Exterior trim: window assemblies, regulators, rack lifts, door frames, roof rail systems -> /, /capabilities", "Automotive products: bumpers/fascias, grilles, exterior trim, subsystem components -> /capabilities", "Capabilities: injection molding, chroming, paint, assembly, tooling, surface finishing, design & engineering -> /about-us, /capabilities", "200+ engineers/technicians for molding -> /, /capabilities", "290,000 sq ft tooling capacity -> /, /capabilities", "Omniluxe\u00ae PVD technology -> /capabilities", "Brilliance paint-over-chrome process -> /capabilities", "Serves automotive OEMs globally -> /, /about-us, /capabilities", "Single-source solutions from concept to completion -> /about-us, /capabilities"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence"